"""Aggiunge i ritratti identificati e i dati delle schede familiari documentate."""
from pathlib import Path
from html import escape
import json,re

def apply_ritratti(root):
 root=Path(root);records=json.loads((root/'content/ritratti-famiglia.json').read_text());p=root/'dist/genealogia.html';s=p.read_text();records=sorted(records,key=lambda c:(c['name'].casefold(),c['birth']));count=sum(bool(c['photo']) for c in records)
 groups=sorted({c['collection'] for c in records});cards=[]
 for c in records:
  photo='<img src="'+escape(c['photo'])+'" alt="" loading="lazy">' if c['photo'] else '<span class="family-no-photo">Foto non disponibile</span>'
  dates=('<span>Nascita: '+escape(c['birth'])+'</span>' if c['birth'] else '<span>Nascita: data non indicata</span>')+('<span>Morte: '+escape(c['death'])+'</span>' if c['death'] else '')
  if c.get('birth_place'):dates+='<span>Luogo di nascita: '+escape(c['birth_place'])+'</span>'
  aliases='<span class="portrait-alias">'+escape(' · '.join(c['aliases']))+'</span>' if c['aliases'] else ''
  cards.append('<button type="button" class="family-portrait-card" data-profile="'+c['id']+'"'+(' hidden' if not c['photo'] else '')+'>'+photo+'<span class="family-card-copy"><strong>'+escape(c['name'])+'</strong>'+aliases+'<span class="family-card-dates">'+dates+'</span><span class="family-card-open">Apri la scheda →</span></span></button>')
 section='<section class="family-portraits" id="ritratti-famiglia" aria-labelledby="family-portraits-title"><p class="eyebrow">I VOLTI DELLA FAMIGLIA</p><h2 class="feature-title" id="family-portraits-title">Ritratti e schede di famiglia</h2><p>'+str(count)+' ritratti identificati, raccolti dalle cartelle di famiglia. Le date provengono dall’albero familiare completo e dalle schede MyHeritage verificate; quando mancano non vengono ricostruite. Le date con anno a due cifre restano come nel documento. Per gli omonimi controlla le date nella scheda.</p><div class="family-portrait-filters"><label>Cerca una persona<input id="family-name-search" type="search" placeholder="Nome, cognome o soprannome…"></label><label>Raccolta<select id="family-collection"><option value="">Tutte le raccolte</option>'+''.join('<option>'+escape(g)+'</option>' for g in groups)+'</select></label><label class="family-checkbox"><input id="family-only-photos" type="checkbox" checked> Solo schede con fotografia</label></div><p id="family-result-count" aria-live="polite"></p><div class="family-portrait-grid">'+''.join(cards)+'</div><p class="family-source-note">Le fotografie sono quelle dell’archivio, senza ricostruzioni dei volti. La raccolta comprende anche persone non presenti nelle due viste interattive precedenti; non sono stati aggiunti collegamenti di parentela non documentati.</p><p><a href="assets/genealogia/famiglia-completa.pdf" target="_blank" rel="noopener">Consulta l’albero familiare completo utilizzato come fonte ↗</a></p></section><dialog id="family-profile" class="family-profile"><button type="button" id="close-family-profile" aria-label="Chiudi scheda di famiglia">Chiudi ×</button><div id="family-profile-content"></div></dialog><script id="family-portraits-data" type="application/json">'+json.dumps(records,ensure_ascii=False).replace('</','<\\/')+'</script>'
 s=s.replace('Nomi, date, ritratti e collegamenti sono trascritti dai due alberi MyHeritage presenti nel sito originale. Le date mancanti non sono state ricostruite; gli anni riportati sono quelli del documento e non indicano lo stato attuale delle persone.','Le due viste interattive integrano gli alberi originali con il ramo di Sante Martinelli e Ines Ardoino, verificato su MyHeritage. Ritratti e date provengono dall’archivio familiare e dalle schede documentate. Le date mancanti non sono state ricostruite e non indicano lo stato attuale delle persone.')
 s=s.replace('</main>',section+'</main>',1)
 s=s.replace('<div class="tree-tabs"','<p class="family-jump"><a class="button secondary" href="#ritratti-famiglia">Sfoglia i '+str(count)+' ritratti di famiglia ↓</a></p><div class="tree-tabs"',1)
 s=s.replace('</head>','<link rel="stylesheet" href="ritratti.css?v=20261113"><script src="ritratti.js?v=famiglie-20261118b" defer></script></head>');s=re.sub(r'genealogia.js\?v=[^\"]+','genealogia.js?v=famiglie-20261118b',s);p.write_text(s)
 print('Ritratti di famiglia:',count,'fotografie e',len(records),'schede documentate.')
